class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        import sys
        sys.setrecursionlimit(300000)
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        gs = set(u * n + v for u, v in guesses)
        def dfs1(u, p):
            c = 0
            for v in g[u]:
                if v != p:
                    c += dfs1(v, u) + (u * n + v in gs)
            return c
        score = [0] * n
        def dfs2(u, p, s):
            score[u] = s
            for v in g[u]:
                if v != p:
                    dfs2(v, u, s - (u * n + v in gs) + (v * n + u in gs))
        dfs2(0, -1, dfs1(0, -1))
        return sum(s >= k for s in score)

