class Solution {
public:
    int rootCount(vector<vector<int>>& edges, vector<vector<int>>& guesses, int k) {
        int n = edges.size() + 1;
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        auto key = [](long long u, long long v){ return u * 100001LL + v; };
        unordered_set<long long> gs;
        for (auto& q : guesses) gs.insert(key(q[0], q[1]));
        vector<int> score(n);
        function<int(int,int)> dfs1 = [&](int u, int p) -> int {
            int c = 0;
            for (int v : g[u]) if (v != p) c += dfs1(v, u) + gs.count(key(u, v));
            return c;
        };
        function<void(int,int,int)> dfs2 = [&](int u, int p, int s) {
            score[u] = s;
            for (int v : g[u]) if (v != p)
                dfs2(v, u, s - gs.count(key(u, v)) + gs.count(key(v, u)));
        };
        dfs2(0, -1, dfs1(0, -1));
        int ans = 0;
        for (int s : score) if (s >= k) ans++;
        return ans;
    }
};

