class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        from collections import deque
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        gs = set(map(tuple, guesses))
        ans = 0
        for r in range(n):
            parent = [-1] * n
            dq = deque([r]); parent[r] = r
            while dq:
                u = dq.popleft()
                for v in g[u]:
                    if parent[v] == -1:
                        parent[v] = u; dq.append(v)
            cnt = sum((u, v) in gs and parent[v] == u for u, v in guesses)
            ans += cnt >= k
        return ans

