            vector<int> par(n, -1); par[r] = r;
            queue<int> dq; dq.push(r);
            while (!dq.empty()) {
                int u = dq.front(); dq.pop();
                for (int v : g[u]) if (par[v] == -1) { par[v] = u; dq.push(v); }
            }
            int cnt = 0;
            for (auto& q : guesses) if (par[q[1]] == q[0]) cnt++;
            ans += cnt >= k;
        }
        return ans;
    }
};

