class Solution {
    public int rootCount(int[][] edges, int[][] guesses, int k) {
        int n = edges.length + 1;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        Set<Long> gs = new HashSet<>();
        for (int[] q : guesses) gs.add(q[0] * 100001L + q[1]);
        int ans = 0;
        for (int r = 0; r < n; r++) {
            int[] par = new int[n]; Arrays.fill(par, -1); par[r] = r;
            Deque<Integer> dq = new ArrayDeque<>(List.of(r));
            while (!dq.isEmpty()) {
                int u = dq.poll();
                for (int v : g.get(u)) if (par[v] == -1) { par[v] = u; dq.push(v); }
            }
            int cnt = 0;
            for (int[] q : guesses) if (gs.contains(q[0] * 100001L + q[1]) && par[q[1]] == q[0]) cnt++;
            if (cnt >= k) ans++;
        }
        return ans;
    }
}

